import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import Image from "next/image";
import Link from "next/link";

export default function UserDashboard() {
  const metrics = [
    { label: "Total Orders", value: 12 },
    { label: "Pending Orders", value: 3 },
    { label: "Total Spending", value: "Rp 4.250.000" },
  ];

  const recentOrders = [
    {
      id: "Facewash",
      product: "Skincare",
      status: "Delivered",
      price: 299000,
    },
    {
      id: "Serum",
      product: "Skincare",
      status: "Processing",
      price: 199000,
    },
  ];

  const recommendedProducts = [
    {
      id: "1",
      name: "Toner",
      price: 350000,
      image: "/shoes.jpg",
    },
    {
      id: "2",
      name: "moisturaizer",
      price: 450000,
      image: "/jacket.jpg",
    },
    {
      id: "3",
      name: "Retinol",
      price: 120000,
      image: "/shirt.jpg",
    },
  ];

  return (
    <div className="space-y-10 p-6">
      <h1 className="text-3xl font-bold">Dashboard</h1>

      {/* ====== METRICS ====== */}
      <div className="grid grid-cols-1 gap-6 md:grid-cols-3">
        {metrics.map((item) => (
          <Card
            key={item.label}
            className="rounded-xl border bg-white shadow-sm transition hover:shadow-md"
          >
            <CardHeader>
              <CardTitle className="text-sm text-gray-500">
                {item.label}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-3xl font-semibold">{item.value}</p>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* ====== RECENT ORDERS ====== */}
      <div>
        <h2 className="mb-4 text-xl font-semibold">Recent Orders</h2>
        <Card className="rounded-xl shadow-sm">
          <CardContent className="p-4">
            <div className="space-y-4">
              {recentOrders.map((order) => (
                <div
                  key={order.id}
                  className="flex items-center justify-between rounded-lg border p-3 transition hover:bg-gray-50"
                >
                  <div>
                    <p className="font-semibold">{order.product}</p>
                    <p className="text-muted-foreground text-sm">{order.id}</p>
                  </div>

                  <Badge
                    variant={
                      order.status === "Delivered" ? "default" : "secondary"
                    }
                  >
                    {order.status}
                  </Badge>

                  <p className="font-medium">
                    Rp {order.price.toLocaleString("id-ID")}
                  </p>

                  <Link href={`/user/orders/${order.id}`}>
                    <Button size="sm" variant="outline">
                      Detail
                    </Button>
                  </Link>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* ====== RECOMMENDED PRODUCTS ====== */}
      <div>
        <h2 className="mb-4 text-xl font-semibold">Recommended for You</h2>

        <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {recommendedProducts.map((product) => (
            <Card
              key={product.id}
              className="overflow-hidden rounded-xl shadow-sm transition hover:shadow-md"
            >
              <div className="relative h-48 w-full">
                <Image
                  src={product.image}
                  alt={product.name}
                  fill
                  className="object-cover"
                />
              </div>

              <CardContent className="space-y-2 p-4">
                <h3 className="text-lg font-semibold">{product.name}</h3>
                <p className="font-medium text-gray-600">
                  Rp {product.price.toLocaleString("id-ID")}
                </p>

                <Link href={`/product/${product.id}`}>
                  <Button className="mt-2 w-full">View Product</Button>
                </Link>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    </div>
  );
}
